    original_T = T
    if T[-1] == 'X':
        T = T[0:2]
    T = T.lower()

    j = 0
    for i in range(len(T)):
        while j < len(S):
            if T[i] == S[j]:
                j += 1
                break
            j += 1
        else:
            return False

    if original_T[-1] == 'X':
        T += 'x'
        j = 0
        for i in range(len(T)):
            while j < len(S):
                if T[i] == S[j]:
                    j += 1
                    break
                j += 1
